// ===== eingebettet aus src/fehlerklassen.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const fehlerklassen = (() => {
const module = { exports: {} };
// Fehlerklassen und Statuscode-Mapping (Masterprompt 3, Bauplan 3).
// EPA-Fehler werden als Text "[EPA:<status>:<CODE>:<Vorgangs-ID|->] <Meldung>" geworfen,
// damit der Error-Handler (EPA-05) sie aus execution.error.message zurücklesen kann.

const FEHLERCODES = Object.freeze({
	UNGUELTIGES_FORMAT: { status: 400, klasse: 'Eingabe', retrybar: false },
	UNGUELTIGER_AUSLOESER: { status: 400, klasse: 'Eingabe', retrybar: false },
	UNBEKANNTER_STATUS: { status: 400, klasse: 'Eingabe', retrybar: false },
	AUTH_FEHLER: { status: 401, klasse: 'Authentifizierung', retrybar: false },
	KEINE_BERECHTIGUNG: { status: 403, klasse: 'Authentifizierung', retrybar: false },
	VORGANG_NICHT_GEFUNDEN: { status: 404, klasse: 'Nicht gefunden', retrybar: false },
	KONFIG_NICHT_GEFUNDEN: { status: 404, klasse: 'Konfiguration', retrybar: false },
	NICHT_GEFUNDEN: { status: 404, klasse: 'Nicht gefunden', retrybar: false },
	DUPLIKAT: { status: 409, klasse: 'Konflikt', retrybar: false },
	UNZULAESSIGER_STATUSWECHSEL: { status: 409, klasse: 'Konflikt', retrybar: false },
	UNZULAESSIGER_AUSLOESER: { status: 409, klasse: 'Konflikt', retrybar: false },
	VERSIONSKONFLIKT: { status: 409, klasse: 'Konflikt', retrybar: true },
	GESPERRT: { status: 409, klasse: 'Konflikt', retrybar: true },
	KONFIG_MEHRDEUTIG: { status: 409, klasse: 'Konfiguration', retrybar: false },
	FREIGABE_ABGELAUFEN: { status: 410, klasse: 'Freigabe', retrybar: false },
	EXTRAKTION_UNGUELTIG: { status: 422, klasse: 'LLM', retrybar: false },
	KONFIGURATIONSFEHLER: { status: 424, klasse: 'Konfiguration', retrybar: false },
	RATE_LIMIT: { status: 429, klasse: 'Upstream', retrybar: true },
	UPSTREAM_FEHLER: { status: 502, klasse: 'Upstream', retrybar: true },
	NICHT_ERREICHBAR: { status: 503, klasse: 'Upstream', retrybar: true },
	ZEITUEBERSCHREITUNG: { status: 504, klasse: 'Upstream', retrybar: true },
	UNBEKANNT: { status: 500, klasse: 'Unbekannt', retrybar: false },
});

// Bei diesen Codes bearbeitet eine andere Ausführung den Vorgang bzw. die Mail ist schon verarbeitet:
// der Vorgang wird NICHT auf "Eskaliert / Manuell" gesetzt (sonst würde ein Parallellauf gestört).
const OHNE_ESKALATION = Object.freeze(['VERSIONSKONFLIKT', 'GESPERRT', 'DUPLIKAT']);

// Fehler aus diesen Workflows werden gemeldet, aber nicht durch "Vorgang sichern" eskaliert: EPA-05 sichert Vorgänge
// selbst über "EPA SW Status setzen". Schlüge das fehl und würde erneut gesichert, entstünde eine Fehlerschleife.
const OHNE_SICHERUNG_AUS = Object.freeze(['EPA SW Status setzen']);

const EPA_MUSTER = /^\[EPA:(\d{3}):([A-Z_]+):([^\]]*)\]\s*([\s\S]*)$/;

function formatEpaFehler(code, vorgangsId, meldung) {
	const def = FEHLERCODES[code] || FEHLERCODES.UNBEKANNT;
	return `[EPA:${def.status}:${FEHLERCODES[code] ? code : 'UNBEKANNT'}:${vorgangsId || '-'}] ${meldung || ''}`.trim();
}

/** Wirft einen EPA-Fehler (für Code-Nodes). */
function epaFehler(code, vorgangsId, meldung) {
	const err = new Error(formatEpaFehler(code, vorgangsId, meldung));
	err.epaCode = code;
	return err;
}

function parseEpaFehler(text) {
	if (typeof text !== 'string') return null;
	// n8n stellt der Meldung manchmal Präfixe voran; das Muster darf irgendwo in der ersten Zeile beginnen.
	const start = text.indexOf('[EPA:');
	if (start < 0) return null;
	const m = text.slice(start).match(EPA_MUSTER);
	if (!m) return null;
	return {
		status: Number(m[1]),
		code: m[2],
		vorgangsId: m[3] === '-' ? null : m[3],
		meldung: m[4].trim(),
	};
}

/** Entfernt personenbezogene Daten und kürzt (keine Mail-Inhalte im Fehlerlog). */
function bereinigeMeldung(text, maxLaenge = 300) {
	if (text === undefined || text === null) return '';
	let s = String(text)
		.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '<email>')
		.replace(/\+?\d[\d\s/().-]{7,}\d/g, '<nummer>')
		.replace(/Bearer\s+[A-Za-z0-9._~+/=-]+/g, 'Bearer <token>')
		.replace(/\s+/g, ' ')
		.trim();
	if (s.length > maxLaenge) s = s.slice(0, maxLaenge - 1) + '…';
	return s;
}

function codeAusHttpStatus(status) {
	const n = Number(status);
	if (!Number.isFinite(n)) return null;
	if (n === 400 || n === 422) return 'UNGUELTIGES_FORMAT';
	if (n === 401) return 'AUTH_FEHLER';
	if (n === 403) return 'KEINE_BERECHTIGUNG';
	if (n === 404) return 'NICHT_GEFUNDEN';
	if (n === 408 || n === 504) return 'ZEITUEBERSCHREITUNG';
	if (n === 409) return 'DUPLIKAT';
	if (n === 429) return 'RATE_LIMIT';
	if (n === 503) return 'NICHT_ERREICHBAR';
	if (n >= 500 && n < 600) return 'UPSTREAM_FEHLER';
	return null;
}

function codeAusText(text) {
	const t = String(text || '');
	if (/timed? ?out|ETIMEDOUT|ESOCKETTIMEDOUT|timeout of \d+ms/i.test(t)) return 'ZEITUEBERSCHREITUNG';
	if (/ECONNREFUSED|ECONNRESET|ENOTFOUND|EAI_AGAIN|socket hang up|service unavailable/i.test(t)) return 'NICHT_ERREICHBAR';
	if (/rate.?limit|too many requests/i.test(t)) return 'RATE_LIMIT';
	if (/invalid_grant|unauthori[sz]ed|token (has )?expired|invalid.?token|authentication failed|password authentication/i.test(t)) return 'AUTH_FEHLER';
	if (/forbidden|insufficient privileges|access denied|permission denied/i.test(t)) return 'KEINE_BERECHTIGUNG';
	if (/duplicate key|unique constraint/i.test(t)) return 'DUPLIKAT';
	return null;
}

/**
 * Klassifiziert einen Fehler.
 * @param {{message?: string, description?: string, httpCode?: string|number}} fehler
 */
function klassifiziereFehler(fehler) {
	const f = fehler || {};
	const epa = parseEpaFehler(f.message) || parseEpaFehler(f.description);
	let code;
	let vorgangsId = null;
	let meldung;
	if (epa) {
		code = FEHLERCODES[epa.code] ? epa.code : 'UNBEKANNT';
		vorgangsId = epa.vorgangsId;
		meldung = epa.meldung;
	} else {
		code = codeAusHttpStatus(f.httpCode) || codeAusText(`${f.message || ''} ${f.description || ''}`) || 'UNBEKANNT';
		meldung = f.message || f.description || '';
	}
	const def = FEHLERCODES[code];
	return {
		statuscode: def.status,
		fehlercode: code,
		klasse: def.klasse,
		retrybar: def.retrybar,
		eskalieren: !OHNE_ESKALATION.includes(code),
		vorgangsId,
		meldung: bereinigeMeldung(meldung),
	};
}

/**
 * Baut aus der Ausgabe des Error Trigger einen Fehlerlog-Eintrag (ohne Mail-Inhalte).
 * Error Trigger liefert entweder {execution, workflow} oder bei Trigger-Fehlern {trigger, workflow}.
 */
function ausErrorTrigger(json) {
	const j = json || {};
	const exec = j.execution || {};
	const err = exec.error || (j.trigger && j.trigger.error) || {};
	const k = klassifiziereFehler({
		message: err.message,
		description: err.description,
		httpCode: err.httpCode,
	});
	const node = (err.node && err.node.name) || exec.lastNodeExecuted || null;
	const workflow = j.workflow || {};
	// Markierung " *" (fehlende Credentials) gehört nicht zum Namen
	const ausSicherung = OHNE_SICHERUNG_AUS.includes(String(workflow.name || '').replace(/\s*\*$/, ''));
	return {
		statuscode: k.statuscode,
		fehlercode: k.fehlercode,
		klasse: k.klasse,
		retrybar: k.retrybar,
		eskalieren: k.eskalieren && Boolean(k.vorgangsId) && !ausSicherung,
		workflow_id: workflow.id || null,
		workflow_name: workflow.name || null,
		node,
		execution_id: exec.id !== undefined && exec.id !== null ? String(exec.id) : null,
		execution_url: exec.url || null,
		modus: exec.mode || (j.trigger && j.trigger.mode) || null,
		vorgangs_id: k.vorgangsId,
		meldung: k.meldung,
	};
}

function escapeHtml(s) {
	return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

// Klartext je Fehlerklasse für die Alarmmeldung (Mitarbeiter sollen verstehen, was passiert ist).
const KLASSE_TEXT = Object.freeze({
	Upstream: 'Ein externer Dienst (Outlook, KI oder Telegram) hat nicht wie erwartet geantwortet.',
	Konfiguration: 'Die Konfiguration ist unvollständig oder fehlerhaft.',
	Authentifizierung: 'Zugangsdaten sind ungültig oder abgelaufen.',
	Konflikt: 'Zwei Abläufe haben sich überschnitten.',
	Eingabe: 'Ein Ablauf hat ungültige Daten erhalten.',
	LLM: 'Die KI hat keine verwertbare Antwort geliefert.',
	Freigabe: 'Eine Freigabe ist abgelaufen.',
	'Nicht gefunden': 'Ein Datensatz wurde nicht gefunden.',
	Unbekannt: 'Ein unerwarteter Fehler ist aufgetreten.',
});

/** Konkrete Handlungsempfehlung aus Fehlercode und Meldung. */
function alarmEmpfehlung(e) {
	const m = String(e.meldung || '').toLowerCase();
	if (/suspend|gesperrt|blocked/.test(m)) return 'Das Postfach-Konto wurde vom Anbieter gesperrt. Im Postfach anmelden und die Bestätigung durchführen. Nicht gesendete Nachrichten kommen danach automatisch mit neuem Link erneut zur Freigabe (Prüfung stündlich).';
	if (/401|unauthori|token|anmeld/.test(m) || e.klasse === 'Authentifizierung') return 'Zugang (Credential) in n8n prüfen und neu verbinden.';
	if (e.klasse === 'Konfiguration') return 'Konfiguration bzw. Regel-Sheet des Kunden prüfen.';
	if (e.retrybar) return 'Meist vorübergehend. Tritt der Fehler wiederholt auf, die Ausführung öffnen und prüfen.';
	return 'Bitte die Ausführung öffnen und prüfen.';
}

function alarmHtml(eintrag) {
	const e = eintrag;
	const meldung = String(e.meldung || '');
	// Titel: erster Satzteil der Meldung ("Rückfrage nicht gesendet: …"), sonst die Fehlerklasse
	const kopf = meldung.split(/[:.]/)[0].trim();
	const titel = kopf && kopf.length <= 70 ? kopf : (KLASSE_TEXT[e.klasse] || 'Systemfehler');
	const zeilen = [
		`🚨 <b>Systemfehler: ${escapeHtml(titel)}</b>`,
		escapeHtml(KLASSE_TEXT[e.klasse] || KLASSE_TEXT.Unbekannt),
	];
	if (e.vorgangs_id) zeilen.push(`Vorgang: <b>${escapeHtml(e.vorgangs_id)}</b>`);
	zeilen.push(`Grund: ${escapeHtml(meldung || '–')}`);
	zeilen.push(`Was tun: ${escapeHtml(alarmEmpfehlung(e))}`);
	zeilen.push('');
	zeilen.push(`Technik: ${escapeHtml(e.workflow_name || e.workflow_id || '?')} · ${escapeHtml(e.node || '?')} · EPA-Fehler ${e.statuscode} ${escapeHtml(e.fehlercode)} (${escapeHtml(e.klasse)})`);
	if (e.execution_url) zeilen.push(`<a href="${escapeHtml(e.execution_url)}">Ausführung ${escapeHtml(e.execution_id)} öffnen</a>`);
	return zeilen.join('<br>');
}

module.exports = {
	FEHLERCODES,
	OHNE_ESKALATION,
	OHNE_SICHERUNG_AUS,
	formatEpaFehler,
	epaFehler,
	parseEpaFehler,
	bereinigeMeldung,
	klassifiziereFehler,
	ausErrorTrigger,
	alarmHtml,
	alarmEmpfehlung,
	escapeHtml,
};
return module.exports;
})();
// ===== Ende src/fehlerklassen.js =====
// ===== eingebettet aus src/datenTabellen.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const datenTabellen = (() => {
const module = { exports: {} };
// Hilfsfunktionen für den Speicher-Adapter "n8n Data Tables".
// Data Tables kennen nur string/number/boolean/date. JSON-Felder werden als Text gespeichert und hier
// beim Lesen geparst bzw. beim Schreiben serialisiert. Der Data-Table-Node übernimmt im Modus
// "autoMapInputData" genau die Felder des Eingabe-Items; deshalb erzeugen diese Funktionen nur
// gültige Spalten (unbekannte Spalten würden den Node abbrechen lassen).

const SPALTEN = {
	epa_vorgaenge: [
		'vorgangs_id', 'kunde_id', 'vorgangstyp', 'status', 'conversation_id', 'erste_message_id', 'letzte_message_id',
		'bekannte_message_ids', 'absender_adresse', 'absender_name', 'betreff', 'betreff_normalisiert', 'extrahierte_daten',
		'fehlende_felder', 'konflikte', 'rundenzaehler', 'antwort_frist', 'erinnerungen_gesendet', 'bearbeiter',
		'freigabe_id_aktuell', 'spoofing_hinweis', 'version', 'lock_bis', 'lock_durch', 'loeschen_ab', 'sprache',
		'erste_mail_am', 'erste_mail_link',
	],
	epa_audit_log: ['kunde_id', 'vorgangs_id', 'typ', 'alt', 'neu', 'ausloeser', 'details', 'referenz'],
};

const JSON_SPALTEN = {
	epa_vorgaenge: { bekannte_message_ids: [], extrahierte_daten: {}, fehlende_felder: [], konflikte: [] },
	epa_audit_log: { details: {} },
};

const OFFEN_AUSGESCHLOSSEN = ['Abgeschlossen', 'Ignoriert'];

function parseJsonSpalte(wert, standard) {
	if (wert === null || wert === undefined || wert === '') return Array.isArray(standard) ? [] : { ...standard };
	if (typeof wert === 'object') return wert;
	try {
		return JSON.parse(wert);
	} catch {
		return Array.isArray(standard) ? [] : { ...standard };
	}
}

/** Item eines Data-Table-Lesezugriffs -> Objekt (oder null, wenn leer, z. B. bei alwaysOutputData). */
function zeileLesen(row, tabelle) {
	if (!row || row.id === undefined || row.id === null) return null;
	const out = { ...row };
	for (const [spalte, standard] of Object.entries(JSON_SPALTEN[tabelle] || {})) out[spalte] = parseJsonSpalte(row[spalte], standard);
	return out;
}

/** Objekt -> schreibbare Zeile (nur bekannte Spalten, JSON als Text, undefined entfernt). */
function zeileSchreiben(obj, tabelle) {
	const erlaubt = SPALTEN[tabelle];
	if (!erlaubt) throw new Error(`Unbekannte Tabelle ${tabelle}`);
	const json = JSON_SPALTEN[tabelle] || {};
	const out = {};
	for (const [k, v] of Object.entries(obj || {})) {
		if (!erlaubt.includes(k)) throw new Error(`Spalte "${k}" gibt es in ${tabelle} nicht`);
		if (v === undefined) continue;
		out[k] = k in json && v !== null && typeof v !== 'string' ? JSON.stringify(v) : v;
	}
	return out;
}

/** Kollisionsfreie Vorgangs-ID aus der fortlaufenden Zeilen-ID der Data Table. */
function vorgangsIdAusZeile(zeilenId, jahr) {
	const n = Number(zeilenId);
	if (!Number.isInteger(n) || n < 1) throw new Error(`Ungültige Zeilen-ID ${zeilenId}`);
	return `V-${jahr}-${String(n).padStart(4, '0')}`;
}

/** Neuer Vorgang (Status "Neu") aus den erlaubten Anlage-Feldern. */
function neuerVorgang(kundeId, daten, { aufbewahrungTage, jetzt, platzhalterId }) {
	const d = daten || {};
	const loeschen = new Date(new Date(jetzt).getTime() + Number(aufbewahrungTage) * 86400000).toISOString();
	return zeileSchreiben({
		vorgangs_id: platzhalterId,
		kunde_id: kundeId,
		vorgangstyp: d.vorgangstyp ?? null,
		status: 'Neu',
		conversation_id: d.conversation_id ?? null,
		erste_message_id: d.erste_message_id ?? null,
		letzte_message_id: d.erste_message_id ?? null,
		bekannte_message_ids: d.erste_message_id ? [d.erste_message_id] : [],
		absender_adresse: d.absender_adresse ? String(d.absender_adresse).toLowerCase() : null,
		absender_name: d.absender_name ?? null,
		betreff: d.betreff ?? null,
		betreff_normalisiert: d.betreff_normalisiert ?? null,
		extrahierte_daten: {},
		fehlende_felder: [],
		konflikte: [],
		rundenzaehler: 0,
		erinnerungen_gesendet: 0,
		spoofing_hinweis: d.spoofing_hinweis ?? null,
		// Eingang und Outlook-Link der ersten Mail, damit die Abschluss-Meldung darauf verweisen kann
		erste_mail_am: d.erste_mail_am ?? null,
		erste_mail_link: d.erste_mail_link ?? null,
		version: 1,
		loeschen_ab: loeschen,
	}, 'epa_vorgaenge');
}

const AENDERBAR = ['vorgangstyp', 'conversation_id', 'letzte_message_id', 'neue_message_ids', 'absender_name', 'betreff',
	'betreff_normalisiert', 'extrahierte_daten', 'fehlende_felder', 'konflikte', 'rundenzaehler', 'antwort_frist',
	'erinnerungen_gesendet', 'bearbeiter', 'freigabe_id_aktuell', 'spoofing_hinweis', 'sprache'];

/**
 * Teil-Update eines Vorgangs. Gibt nur geänderte Spalten + neue Version zurück.
 * neue_message_ids werden an bekannte_message_ids angehängt (ohne Duplikate).
 */
function aktualisierungBerechnen(vorgang, daten) {
	const patch = {};
	for (const [k, v] of Object.entries(daten || {})) {
		if (!AENDERBAR.includes(k)) throw new Error(`Feld "${k}" ist nicht änderbar`);
		if (k === 'neue_message_ids') {
			const alle = [...(vorgang.bekannte_message_ids || []), ...(v || [])];
			patch.bekannte_message_ids = [...new Set(alle)];
		} else {
			patch[k] = v;
		}
	}
	patch.version = Number(vorgang.version) + 1;
	return zeileSchreiben(patch, 'epa_vorgaenge');
}

/** Filtert offene Vorgänge eines Kunden nach Zuordnungskriterien (wie die SQL-Variante). */
/** Erfasste Werte eines Vorgangs als Texte (höchstens 15). */
function erfassteWerte(daten) {
	const out = [];
	for (const d of Object.values(daten && typeof daten === 'object' ? daten : {})) {
		const w = d && typeof d === 'object' ? d.wert : null;
		if (w !== null && w !== undefined && w !== '') out.push(String(w));
	}
	return out.slice(0, 15);
}

function kandidatenFiltern(zeilen, kriterien) {
	const k = kriterien || {};
	const ids = new Set(k.message_ids || []);
	const vids = new Set(k.vorgangs_ids || []);
	const absender = k.absender_adresse ? String(k.absender_adresse).toLowerCase() : null;
	// Starke Hinweise (Bezug auf Message-ID, genannte Vorgangs-ID, gleiche Konversation) sind immer Kandidaten.
	// Schwache (nur Absender oder Betreff) werden nach Aktualität auf insgesamt 20 aufgefüllt. Sonst fällt bei
	// Absendern mit vielen offenen Vorgängen ausgerechnet der genannte Vorgang heraus (Live-Test T04b).
	const stark = (v) => (v.bekannte_message_ids || []).some((m) => ids.has(m)) || vids.has(v.vorgangs_id) ||
		Boolean(k.conversation_id && v.conversation_id === k.conversation_id);
	const passend = (zeilen || [])
		.map((z) => zeileLesen(z, 'epa_vorgaenge'))
		.filter((v) => v && !OFFEN_AUSGESCHLOSSEN.includes(v.status))
		.filter((v) => stark(v) ||
			(absender && String(v.absender_adresse || '').toLowerCase() === absender) ||
			(k.betreff_normalisiert && v.betreff_normalisiert === k.betreff_normalisiert))
		.sort((a, b) => String(b.updatedAt || '').localeCompare(String(a.updatedAt || '')));
	const starke = passend.filter(stark);
	const schwache = passend.filter((v) => !stark(v)).slice(0, Math.max(0, 20 - starke.length));
	return [...starke, ...schwache]
		.map((v) => ({
			vorgangs_id: v.vorgangs_id, status: v.status, conversation_id: v.conversation_id,
			bekannte_message_ids: v.bekannte_message_ids, absender_adresse: v.absender_adresse,
			betreff_normalisiert: v.betreff_normalisiert, version: v.version, geaendert_am: v.updatedAt,
			// Für Meldungen zu Mails ohne Bezug (z. B. Stornierung): Betreff und erfasste Werte zum Abgleich mit dem Text
			betreff: v.betreff, werte: erfassteWerte(v.extrahierte_daten),
		}));
}

/**
 * Entscheidet über eine Sperre. Ergebnis enthält die Werte für ein bedingtes Update
 * (Compare-and-Set auf lock_durch): Nur wenn lock_durch noch den gelesenen Wert hat, wird gesperrt.
 */
function sperreEntscheiden(vorgang, wer, sekunden, jetzt) {
	const t = new Date(jetzt).getTime();
	const bis = vorgang.lock_bis ? new Date(vorgang.lock_bis).getTime() : null;
	const frei = !vorgang.lock_durch || bis === null || bis < t || vorgang.lock_durch === wer;
	return {
		moeglich: frei,
		vorher_durch: vorgang.lock_durch || null,
		vorher_bis: vorgang.lock_bis || null,
		neu: { lock_durch: wer, lock_bis: new Date(t + sekunden * 1000).toISOString() },
	};
}

module.exports = {
	SPALTEN,
	JSON_SPALTEN,
	AENDERBAR,
	zeileLesen,
	zeileSchreiben,
	vorgangsIdAusZeile,
	neuerVorgang,
	aktualisierungBerechnen,
	kandidatenFiltern,
	sperreEntscheiden,
};
return module.exports;
})();
// ===== Ende src/datenTabellen.js =====

// ----- Node-Logik -----
const AKTIONEN = ["lesen","anlegen","aktualisieren","kandidaten_suchen","sperren","entsperren"];
const ANLEGBAR = ['vorgangstyp', 'conversation_id', 'erste_message_id', 'absender_adresse', 'absender_name', 'betreff',
	'betreff_normalisiert', 'spoofing_hinweis', 'erste_mail_am', 'erste_mail_link'];
const e = $input.first().json;
const vid = typeof e.vorgangs_id === 'string' ? e.vorgangs_id.trim() : '';
const fehler = (code, text) => fehlerklassen.epaFehler(code, vid || null, text);
if (!AKTIONEN.includes(e.aktion)) throw fehler('UNGUELTIGES_FORMAT', `Aktion "${e.aktion}" ist unbekannt`);
if (typeof e.kunde_id !== 'string' || !e.kunde_id.trim()) throw fehler('UNGUELTIGES_FORMAT', 'kunde_id fehlt');
const daten = e.daten && typeof e.daten === 'object' && !Array.isArray(e.daten) ? e.daten : {};
const brauchtId = ['lesen', 'aktualisieren', 'sperren', 'entsperren'].includes(e.aktion);
if (brauchtId && !/^V-\d{4}-\d{4,}$/.test(vid)) throw fehler('UNGUELTIGES_FORMAT', `vorgangs_id "${vid}" ist ungültig`);
if (e.aktion === 'aktualisieren') {
	const unbekannt = Object.keys(daten).filter((k) => !datenTabellen.AENDERBAR.includes(k));
	if (unbekannt.length) throw fehler('UNGUELTIGES_FORMAT', `Nicht änderbare Felder: ${unbekannt.join(', ')}`);
	if (Object.keys(daten).length === 0) throw fehler('UNGUELTIGES_FORMAT', 'Keine Änderungen übergeben');
	if (!Number.isInteger(e.erwartete_version)) throw fehler('UNGUELTIGES_FORMAT', 'erwartete_version ist Pflicht beim Aktualisieren');
	if ('neue_message_ids' in daten && !Array.isArray(daten.neue_message_ids)) throw fehler('UNGUELTIGES_FORMAT', 'neue_message_ids muss eine Liste sein');
}
if (e.aktion === 'anlegen') {
	const unbekannt = Object.keys(daten).filter((k) => !ANLEGBAR.includes(k));
	if (unbekannt.length) throw fehler('UNGUELTIGES_FORMAT', `Nicht anlegbare Felder: ${unbekannt.join(', ')}`);
}
const lockSekunden = e.lock_sekunden === undefined || e.lock_sekunden === null ? 300 : Number(e.lock_sekunden);
if (e.aktion === 'sperren' && (!Number.isInteger(lockSekunden) || lockSekunden < 10 || lockSekunden > 3600)) {
	throw fehler('UNGUELTIGES_FORMAT', 'lock_sekunden muss zwischen 10 und 3600 liegen');
}
return [{ json: {
	aktion: e.aktion,
	kunde_id: e.kunde_id.trim(),
	vorgangs_id: vid || null,
	daten,
	erwartete_version: Number.isInteger(e.erwartete_version) ? e.erwartete_version : null,
	referenz: e.referenz ? String(e.referenz) : String($execution.id),
	lock_sekunden: lockSekunden,
} }];

