	throw fehlerklassen.epaFehler('VERSIONSKONFLIKT', e.vorgangs_id, `erwartet Version ${e.erwartete_version}, aktuell ${v.version}`);
}
return [{ json: datenTabellen.aktualisierungBerechnen(v, e.daten) }];

